<script setup>
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {loadTagSuggestions} from '@/composables/useGalleryData'
const props=defineProps({modelValue:{type:Array,default:()=>[]},names:{type:Object,default:()=>({})}}),emit=defineEmits(['update:modelValue'])
const input=ref(null),query=ref(''),suggestions=ref([]),localNames=ref({}),chinese=ref(true),highlight=ref(-1),error=ref('')
const groups=computed(()=>{const result={};for(const tag of props.modelValue){const split=tag.indexOf(':');const ns=split<0?'other':tag.slice(0,split);(result[ns]??=[]).push({tag,value:split<0?tag:tag.slice(split+1)})}return result})
let timer,controller
watch(query,value=>{clearTimeout(timer);controller?.abort();suggestions.value=[];highlight.value=-1;error.value='';if(value.trim().length<2)return;controller=new AbortController();const request=controller;timer=setTimeout(async()=>{try{const result=await loadTagSuggestions(value.trim(),request.signal);if(controller!==request)return;suggestions.value=result.items.filter(item=>!props.modelValue.includes(item.tag))}catch(e){if(e.name!=='AbortError')error.value='标签检索暂不可用，请重试'}},160)})
function add(item){if(!props.modelValue.includes(item.tag)){emit('update:modelValue',[...props.modelValue,item.tag]);localNames.value[item.tag]=item.tag_cn}query.value='';suggestions.value=[];input.value?.focus()}
function key(e){if(e.key==='Escape'){suggestions.value=[];return}if(['ArrowDown','ArrowUp'].includes(e.key)&&suggestions.value.length){e.preventDefault();highlight.value=(highlight.value+(e.key==='ArrowDown'?1:-1)+suggestions.value.length)%suggestions.value.length}else if(e.key==='Enter'){e.preventDefault();if(suggestions.value[highlight.value>=0?highlight.value:0])add(suggestions.value[highlight.value>=0?highlight.value:0])}}
onBeforeUnmount(()=>{clearTimeout(timer);controller?.abort()})
</script>
<template><div class="ops-tag-editor"><div class="ops-section-title"><label>分类标签 <small>{{modelValue.length}}</small></label><button type="button" class="a-text-button" @click="chinese=!chinese">{{chinese?'中文 / EN':'EN / 中文'}}</button></div><div class="ops-tag-groups"><div v-for="(tags,ns) in groups" :key="ns" class="ops-tag-group"><strong>{{ns}}</strong><div><span v-for="tag in tags" :key="tag.tag" class="ops-tag" :title="tag.tag"><span>{{chinese?(localNames[tag.tag]||names[tag.tag]||tag.value):tag.value}}</span><button type="button" :aria-label="'移除标签 '+tag.tag" @click="emit('update:modelValue',modelValue.filter(t=>t!==tag.tag))">×</button></span></div></div><p v-if="!modelValue.length" class="ops-muted">尚无标签，可从标签库检索添加。</p></div><div class="ops-search"><input ref="input" v-model="query" class="v2-input" aria-label="添加标签" placeholder="搜索中文、英文或 f: / a: 等命名空间…" role="combobox" aria-controls="editor-tag-options" :aria-expanded="suggestions.length>0" :aria-activedescendant="highlight>=0?'editor-tag-'+highlight:undefined" @keydown="key"/><div v-if="suggestions.length" id="editor-tag-options" role="listbox" class="ops-suggestions"><button v-for="(item,index) in suggestions" :id="'editor-tag-'+index" :key="item.tag" type="button" role="option" :aria-selected="highlight===index" @click="add(item)"><strong>{{item.tag_cn||item.value}}</strong><small>{{item.tag}}</small><span>＋</span></button></div></div><small class="ops-muted">输入至少两个字符，使用 ↑ ↓ 选择、Enter 添加；已有标签不会重复添加。</small><p v-if="error" role="status">{{error}}</p></div></template>
